#include <iostream>
#include <map>
#include <algorithm>

using namespace std;

using ll = long long;

ll a[6], ini;

map<ll, map<ll, map<ll, bool>>> visited;
map<ll, map<ll, ll>> best;

bool dfs(ll s, ll l, ll g) {
    if (s < 0 || l < 0 || g < 0) return false;
    if (s > ini) return true;

    auto &currentBest = best[s][l];
    if (currentBest != 0 && currentBest - 1 < g) return true;
    if (currentBest == 0 || g < currentBest - 1) currentBest = g + 1;

    if (visited[s][l][g]) return false;
    visited[s][l][g] = true;

    if (dfs(s - a[0], l + a[1], g)) return true;
    if (dfs(s, l - a[2], g + a[3])) return true;
    if (dfs(s + a[5], l, g - a[4])) return true;

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    for (ll &x : a) cin >> x;

    ini = max(a[0], 1LL) * max(a[2], 1LL) * max(a[4], 1LL);

    cout << (dfs(ini, 0, 0) ? "Ron" : "Hermione") << '\n';
    return 0;
}

